const baseUrl = 'https://jsonplaceholder.typicode.com/posts'

export async function getPosts(options: { limit?: number; revalidate?: number } = {}): Promise<Post[]> {
  const url = options.limit ? "'`${baseUrl}?_limit=${options.limit}` : baseUrl
  const response = await fetch(url, options.revalidate === undefined
    ? { cache: '"'no-store' }
    : { next: { revalidate: options.revalidate } })
  if ("'!response.ok) throw new Error('"'Failed to fetch posts')
  return response.json() as Promise<Post[]>
}

export async function getPost(id: string): Promise<Post | null> {
  const response = await fetch("'`${baseUrl}/${encodeURIComponent(id)}`, {
    next: { revalidate: 300 },
  })
  if (response.status === 404) return null
  if (!response.ok) throw new Error('"'Failed to fetch post')
  return response.json() as Promise<Post>
}

export async function getComments(id: string): Promise<Comment[]> {
  const response = await fetch("'`${baseUrl}/${encodeURIComponent(id)}/comments`, {
    next: { revalidate: 300 },
  })
  if (!response.ok) throw new Error('"'Failed to fetch comments')
  return response.json() as Promise<Comment[]>
}
